import React, { useContext } from 'react';
import { UserContext } from '../context/UserContext';
import axios from 'axios';

const Eliminar = ({ userId }) => {
    const { eliminar } = useContext(UserContext);

    const confirmAndDelete = async () => {
        // eslint-disable-next-line no-restricted-globals
        if (confirm("¿Quieres eliminar este usuario?")) {
            try {
                // Enviar la solicitud DELETE con el ID del usuario
                const response = await axios.delete('http://localhost/SERVIDOR/practica/delete_user.php', {
                    data: { id: userId }  // Enviar el ID del usuario en el cuerpo
                });
                
                if (response.data.success) {
                    eliminar(userId);  // Actualizar el estado global
                    alert('Usuario eliminado con éxito');
                    console.log(`Usuario con ID ${userId} eliminado.`);
                } else {
                    alert('Hubo un error al eliminar el usuario: ' + response.data.message);
                }
            } catch (error) {
                console.error('Error al eliminar el usuario:', error);
                alert('Error al eliminar el usuario.');
            }
        }
    };

    return (
        <button onClick={confirmAndDelete} style={{ color: 'red' }}>
            Eliminar
        </button>
    );
};

export default Eliminar;
